window.makeIronCrystalV216=(()=>{const data=[{"position":"","uv":"","index":""},{"position":"","uv":"","index":""},{"position":"","uv":"","index":""}],textures={"map":"data:image/jpeg;base64,","normalMap":"data:image/jpeg;base64,","roughnessMap":"data:image/jpeg;base64,","metalnessMap":"data:image/jpeg;base64,"};let geos,mat;return function(T){if(!geos){const decode=(s,C)=>{const b=Uint8Array.from(atob(s),c=>c.charCodeAt(0));return new C(b.buffer)};geos=data.map(d=>{const g=new T.BufferGeometry();g.setAttribute('position',new T.BufferAttribute(decode(d.position,Float32Array),3));g.setAttribute('uv',new T.BufferAttribute(decode(d.uv,Float32Array),2));g.setIndex(new T.BufferAttribute(decode(d.index,Uint32Array),1));g.computeVertexNormals();g.computeBoundingSphere();return g});const maps={};for(const [k,url]of Object.entries(textures)){maps[k]=new T.TextureLoader().load(url);if(k==='map')maps[k].colorSpace=T.SRGBColorSpace;}mat=new T.MeshStandardMaterial({...maps,roughness:.8,metalness:.65});}const lod=new T.LOD();geos.forEach((g,i)=>{const mesh=new T.Mesh(g,mat);mesh.castShadow=i===0;mesh.receiveShadow=true;lod.addLevel(mesh,[0,20,45][i]);});return lod;};})();